import React, { useState } from 'react';

function AddItem() {
  const [formData, setFormData] = useState({
    itemId: '',
    itemName: '',
    itemCategory: '',
    itemQty: '',
    itemDetails: '',
    itemImage: null
  });

  const handleChange = (e) => {
    const { name, value, type, files } = e.target;
    
    if (type === 'file') {
      setFormData(prevData => ({
        ...prevData,
        [name]: files[0]
      }));
    } else {
      setFormData(prevData => ({
        ...prevData,
        [name]: value
      }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    // Here you can add your logic to handle the form submission
    console.log('Form submitted with data:', formData);
    
    // Example: Send data to an API
    // You can create a FormData object if you need to upload the image
    const submitData = new FormData();
    submitData.append('itemId', formData.itemId);
    submitData.append('itemName', formData.itemName);
    submitData.append('itemCategory', formData.itemCategory);
    submitData.append('itemQty', formData.itemQty);
    submitData.append('itemDetails', formData.itemDetails);
    if (formData.itemImage) {
      submitData.append('itemImage', formData.itemImage);
    }
    
    // Reset form after submission (optional)
    setFormData({
      itemId: '',
      itemName: '',
      itemCategory: '',
      itemQty: '',
      itemDetails: '',
      itemImage: null
    });
    
    // Clear file input
    document.getElementById('itemImage').value = '';
    
    alert('Item added successfully!');
  };

  return (
    <div className="add-item-container">
      <p className="auth_topic">Add Item</p>

      <div className="form_container">
        <form id="itemForm" onSubmit={handleSubmit}>
          {/* Item ID */}
          <label htmlFor="itemId">Item ID:</label>
          <br />
          <input
            type="text"
            id="itemId"
            name="itemId"
            value={formData.itemId}
            onChange={handleChange}
            required
          />
          <br /><br />

          {/* Item Name */}
          <label htmlFor="itemName">Item Name:</label>
          <br />
          <input
            type="text"
            id="itemName"
            name="itemName"
            value={formData.itemName}
            onChange={handleChange}
            required
          />
          <br /><br />

          {/* Item Category */}
          <label htmlFor="itemCategory">Item Category:</label>
          <br />
          <select
            id="itemCategory"
            name="itemCategory"
            value={formData.itemCategory}
            onChange={handleChange}
            required
          >
            <option value="" disabled>
              Select Item Category
            </option>
            <option value="Apparel & Fashion">Apparel & Fashion</option>
            <option value="Electronics & Gadgets">Electronics & Gadgets</option>
            <option value="Health & Beauty">Health & Beauty</option>
            <option value="Food & Dining">Food & Dining</option>
            <option value="Home & Furniture">Home & Furniture</option>
          </select>
          <br /><br />

          {/* Item Quantity */}
          <label htmlFor="itemQty">Item Quantity:</label>
          <br />
          <input
            type="number"
            id="itemQty"
            name="itemQty"
            value={formData.itemQty}
            onChange={handleChange}
            required
          />
          <br /><br />

          {/* Item Details */}
          <label htmlFor="itemDetails">Item Details:</label>
          <br />
          <textarea
            id="itemDetails"
            name="itemDetails"
            value={formData.itemDetails}
            onChange={handleChange}
            required
          />
          <br /><br />

          {/* Item Image */}
          <label htmlFor="itemImage">Item Image:</label>
          <br />
          <input
            type="file"
            id="itemImage"
            name="itemImage"
            onChange={handleChange}
            accept="image/*"
          />
          <br /><br />

          {/* Submit Button */}
          <button type="submit" className="form_btn">
            Add Item
          </button>
        </form>
      </div>
    </div>
  );
}

export default AddItem;
